/* story-form-7 — journal drama + Antenna Op beat UI */
.journal-drama-list { display: grid; gap: 0.75rem; margin: 0.5rem 0 1rem; }
.journal-drama {
  padding: 0.85rem 1rem;
  border-radius: 10px;
  background: linear-gradient(135deg, rgba(40,24,16,.92), rgba(20,14,10,.88));
  border: 1px solid rgba(232,180,120,.35);
  color: #f2e6d8;
}
.journal-drama.soft { border-color: rgba(180,200,160,.4); }
.journal-drama.sharp { border-color: rgba(196,92,62,.55); }
.journal-drama.spotlight { box-shadow: 0 0 0 1px rgba(232,180,120,.25), 0 8px 24px rgba(0,0,0,.35); }
.journal-drama .rp-kicker { margin: 0 0 0.25rem; font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; opacity: 0.8; }
.journal-drama h3 { margin: 0 0 0.35rem; font-size: 1.05rem; }
.antenna-beat-card {
  padding: 0.75rem 0.9rem;
  margin: 0.4rem 0;
  border-left: 3px solid #e8b478;
  background: rgba(18,12,8,.75);
  color: #f2e6d8;
}
.antenna-beat-card.is-done { opacity: 0.65; border-left-color: #7a9a6a; }
.antenna-beat-card.is-live { border-left-color: #c45c3e; box-shadow: inset 0 0 0 1px rgba(196,92,62,.35); }
.antenna-beat-card h4 { margin: 0 0 0.25rem; font-size: 0.95rem; }
.rp-arc-beat-banner {
  position: relative;
  z-index: 7;
  margin: 0.4rem 0.75rem;
  padding: 0.55rem 0.75rem;
  border-radius: 8px;
  background: rgba(18,12,8,.88);
  color: #f2e6d8;
  border: 1px solid rgba(232,180,120,.45);
  display: flex;
  gap: 0.5rem;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
}
.recap-list.is-collapsed { max-height: 0; overflow: hidden; opacity: 0; }
details.journal-log-fold > summary {
  cursor: pointer;
  color: rgba(242,230,216,.7);
  font-size: 0.85rem;
}

